  def reply(client, id, params \\ nil, opts \\ []) do
    {params, opts} = BillionSend.Client.optional_body(params, opts, true)

    BillionSend.Client.call(
      client,
      "POST",
      "/emails/receiving/#{BillionSend.Client.encode_path(id)}/reply",
      opts,
