      body: params
    )
  end

  @doc "Like `update/4`, but returns the answer or raises."
  @spec update!(BillionSend.Client.t(), String.t(), map() | list() | nil, keyword()) :: term()
  def update!(client, inbox_id, params, opts \\ []) do
    BillionSend.Client.unwrap!(update(client, inbox_id, params, opts))
  end
end

defmodule BillionSend.Inboxes.Codes do
  @moduledoc """
  Operations on inboxes codes.
  """
  @doc """
  Get latest code.

  BillionSend extension: the newest code or sign-in link in delivered mail, never from held mail or senders that failed authentication; links are never fetched. max_age counts from delivery, so a code released from quarantine counts from its release; since skips mail received at or before it, so a second sign-in waits for its own code. wait > 0 long-polls until one arrives (status timeout when none did). Always 200; status none when there is nothing.

  `GET /inboxes/{inbox_id}/codes/latest`

  Options:

    * `:from` - query `from`
    * `:wait` - query `wait`
    * `:max_age` - query `max_age`
    * `:since` - query `since`
    * `:extra_headers`, `:timeout`
  """
  @spec latest(BillionSend.Client.t(), String.t(), keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def latest(client, inbox_id, opts \\ []) do
    BillionSend.Client.call(
      client,
      "GET",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/codes/latest",
      opts,
      query: [{"from", :from}, {"wait", :wait}, {"max_age", :max_age}, {"since", :since}]
    )
  end

  @doc "Like `latest/3`, but returns the answer or raises."
  @spec latest!(BillionSend.Client.t(), String.t(), keyword()) :: term()
  def latest!(client, inbox_id, opts \\ []) do
    BillionSend.Client.unwrap!(latest(client, inbox_id, opts))
  end
end

defmodule BillionSend.Inboxes.Drafts do
  @moduledoc """
  Operations on inboxes drafts.
  """
  @doc """
  List drafts.

  Unsent drafts (draft and pending_approval), most recently updated first; `after` pages toward older ones.

  `GET /inboxes/{inbox_id}/drafts`

  Options:

    * `:limit` - query `limit`
    * `:after` - query `after`
    * `:before` - query `before`
    * `:extra_headers`, `:timeout`
  """
  @spec list(BillionSend.Client.t(), String.t(), keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def list(client, inbox_id, opts \\ []) do
    BillionSend.Client.call(
      client,
      "GET",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts",
      opts,
      query: [{"limit", :limit}, {"after", :after}, {"before", :before}]
    )
  end

  @doc "Like `list/3`, but returns the answer or raises."
  @spec list!(BillionSend.Client.t(), String.t(), keyword()) :: term()
  def list!(client, inbox_id, opts \\ []) do
    BillionSend.Client.unwrap!(list(client, inbox_id, opts))
  end

  @doc """
  Every item of `list`, as a lazy Stream that fetches pages as it goes.

  Walks in the list's own order, from `:after` (or the first page) on; pass
  `:before` instead to walk the other way. Raises the errors `list!` raises.
  """
  @spec list_all(BillionSend.Client.t(), String.t(), keyword()) :: Enumerable.t()
  def list_all(client, inbox_id, opts \\ []) do
    BillionSend.Pagination.stream(
      fn page_after, page_before ->
        list(client, inbox_id, Keyword.merge(opts, after: page_after, before: page_before))
      end,
      Keyword.get(opts, :after),
      Keyword.get(opts, :before)
    )
  end

  @doc """
  Create a draft.

  A standalone draft, or with `thread_id` and `reply_to_email_id` a reply draft in that thread. One unsent reply draft per email: creating another answers 200 with the existing one. A reply draft copies no recipients; set `to` before sending. `attachments` are kept encrypted with the draft until it is sent, rejected, expired or deleted. Nothing is sent until POST /inboxes/{inbox_id}/drafts/{draft_id}/send, or until `send_at` (BillionSend extension) when it is given: the draft is then sent as the caller at that time, through every rule and limit, and must have a recipient. With `send_at`, a reply draft for an email that already has one answers 409 instead of the existing draft.

  `POST /inboxes/{inbox_id}/drafts`

  Options:

    * `:extra_headers`, `:timeout`
  """
  @spec create(BillionSend.Client.t(), String.t(), map() | list() | nil, keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def create(client, inbox_id, params \\ nil, opts \\ []) do
    {params, opts} = BillionSend.Client.optional_body(params, opts, true)

    BillionSend.Client.call(
      client,
      "POST",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts",
      opts,
      body: params
    )
  end

  @doc "Like `create/4`, but returns the answer or raises."
  @spec create!(BillionSend.Client.t(), String.t(), map() | list() | nil, keyword()) :: term()
  def create!(client, inbox_id, params \\ nil, opts \\ []) do
    BillionSend.Client.unwrap!(create(client, inbox_id, params, opts))
  end

  @doc """
  Retrieve a draft.

  One draft with its body, also after it was sent (status sent, email_id set).

  `GET /inboxes/{inbox_id}/drafts/{draft_id}`

  Options:

    * `:extra_headers`, `:timeout`
  """
  @spec get(BillionSend.Client.t(), String.t(), String.t(), keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def get(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.call(
      client,
      "GET",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts/#{BillionSend.Client.encode_path(draft_id)}",
      opts,
      []
    )
  end

  @doc "Like `get/4`, but returns the answer or raises."
  @spec get!(BillionSend.Client.t(), String.t(), String.t(), keyword()) :: term()
  def get!(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.unwrap!(get(client, inbox_id, draft_id, opts))
  end

  @doc """
  Update a draft.

  Each given field replaces the stored one; null clears it. Setting html or text replaces the whole body: the part left out becomes null. `attachments` replaces the whole list (null or an empty list removes the files). A sent draft, or one that changed during the request, answers 409. An edit by an agent sends a draft waiting for approval back to draft. `send_at` (BillionSend extension) schedules the draft to be sent as the caller, or reschedules it, and clears `send_error`; null cancels the schedule. A draft waiting for approval cannot be scheduled (409). When the scheduled send goes out, the draft becomes sent; when the inbox's rules hold it, pending_approval; when it is refused (the key revoked, the inbox deleted, a limit reached), it stays a draft with `send_at` null, `send_error` set and an `inbox.draft.send_failed` webhook.

  `PATCH /inboxes/{inbox_id}/drafts/{draft_id}`

  Options:

    * `:extra_headers`, `:timeout`
  """
  @spec update(BillionSend.Client.t(), String.t(), String.t(), map() | list() | nil, keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def update(client, inbox_id, draft_id, params \\ nil, opts \\ []) do
    {params, opts} = BillionSend.Client.optional_body(params, opts, true)

    BillionSend.Client.call(
      client,
      "PATCH",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts/#{BillionSend.Client.encode_path(draft_id)}",
      opts,
      body: params
    )
  end

  @doc "Like `update/5`, but returns the answer or raises."
  @spec update!(BillionSend.Client.t(), String.t(), String.t(), map() | list() | nil, keyword()) ::
          term()
  def update!(client, inbox_id, draft_id, params \\ nil, opts \\ []) do
    BillionSend.Client.unwrap!(update(client, inbox_id, draft_id, params, opts))
  end

  @doc """
  Delete a draft.

  Removes an unsent draft; a sent one answers 409.

  `DELETE /inboxes/{inbox_id}/drafts/{draft_id}`

  Options:

    * `:extra_headers`, `:timeout`
  """
  @spec delete(BillionSend.Client.t(), String.t(), String.t(), keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def delete(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.call(
      client,
      "DELETE",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts/#{BillionSend.Client.encode_path(draft_id)}",
      opts,
      []
    )
  end

  @doc "Like `delete/4`, but returns the answer or raises."
  @spec delete!(BillionSend.Client.t(), String.t(), String.t(), keyword()) :: term()
  def delete!(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.unwrap!(delete(client, inbox_id, draft_id, opts))
  end

  @doc """
  Reject a draft.

  BillionSend extension: a person or a team-wide full access key turns down a draft waiting for approval. It stays readable with status rejected; webhooks report it deleted.

  `POST /inboxes/{inbox_id}/drafts/{draft_id}/reject`

  Options:

    * `:extra_headers`, `:timeout`
  """
  @spec reject(BillionSend.Client.t(), String.t(), String.t(), keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def reject(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.call(
      client,
      "POST",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts/#{BillionSend.Client.encode_path(draft_id)}/reject",
      opts,
      []
    )
  end

  @doc "Like `reject/4`, but returns the answer or raises."
  @spec reject!(BillionSend.Client.t(), String.t(), String.t(), keyword()) :: term()
  def reject!(client, inbox_id, draft_id, opts \\ []) do
    BillionSend.Client.unwrap!(reject(client, inbox_id, draft_id, opts))
  end

  @doc """
  Send a draft.

  Sends the draft from the inbox address; the body is optional and only ever holds `headers`, which are not supported (an empty value is fine), and an `Idempotency-Key` is accepted. Answers the sent email's id. A draft waiting for approval goes out only when a person or a team-wide full access key sends it (403 approval_required otherwise), and their send skips the inbox's rules but never the team's limits or the shared domain's rules. An agent's send of a draft runs the rules and may hold it (202).

  Sent with an Idempotency-Key: `:idempotency_key` when given, else one made up for this call, so that its retries never send twice.

  `POST /inboxes/{inbox_id}/drafts/{draft_id}/send`

  Options:

    * `:idempotency_key` - see "Sending once" in the README
    * `:extra_headers`, `:timeout`
  """
  @spec send(BillionSend.Client.t(), String.t(), String.t(), map() | list() | nil, keyword()) ::
          {:ok, term()} | {:error, BillionSend.Errors.t()}
  def send(client, inbox_id, draft_id, params \\ nil, opts \\ []) do
    {params, opts} = BillionSend.Client.optional_body(params, opts, true)

    BillionSend.Client.call(
      client,
      "POST",
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/drafts/#{BillionSend.Client.encode_path(draft_id)}/send",
      opts,
      body: params,
      idempotent: true,
      extra: [:idempotency_key]
    )
  end

  @doc "Like `send/5`, but returns the answer or raises."
  @spec send!(BillionSend.Client.t(), String.t(), String.t(), map() | list() | nil, keyword()) ::
          term()
  def send!(client, inbox_id, draft_id, params \\ nil, opts \\ []) do
    BillionSend.Client.unwrap!(send(client, inbox_id, draft_id, params, opts))
  end
end

defmodule BillionSend.Inboxes.Events do
  @moduledoc """
  Operations on inboxes events.
  """
  @doc """
  Stream inbox events.

  BillionSend extension: a server-sent event stream of every inbox event of the team, named like the webhook events (inbox.email.received, inbox.thread.created, email.received, …; types narrows them), each carrying the webhook payload's data. Send the key as a Bearer header; the stream stays open, and a client that reconnects with Last-Event-ID resumes without losing events. Needs a team-wide key: a key held to one domain streams one inbox at a time. An agent (an inbox-scoped key, or an MCP connection) never receives the events about held mail (inbox.email.quarantined), replay included, and naming them in types is a 403. A stream closes within a few seconds once its key is revoked, its person leaves the team or its inbox is gone; it is also closed every ten minutes or so, and the client reconnects with Last-Event-ID. Streams are capped per key and per team on each API process (429 too_many_streams).

  `GET /inboxes/events`

  Options:

    * `:types` - query `types`
    * `:last_event_id` - query `last_event_id`
    * `:last_event_id` - resume after this position
    * `:max_reconnects` - default 5
    * `:extra_headers`, `:timeout`

  Returns `{:ok, stream}`, a lazy Enumerable of `BillionSend.InboxStreamEvent` and `BillionSend.StreamGapEvent` structs (see `BillionSend.EventStream`), or `{:error, error}` when the API refuses the stream.
  """
  @spec stream(BillionSend.Client.t(), keyword()) ::
          {:ok, Enumerable.t()} | {:error, BillionSend.Errors.t()}
  def stream(client, opts \\ []) do
    BillionSend.Client.check_opts!(
      opts,
      [:types, :last_event_id, :max_reconnects, :extra_headers, :timeout],
      []
    )

    BillionSend.EventStream.open(
      client,
      "/inboxes/events",
      [{"types", Keyword.get(opts, :types)}],
      opts
    )
  end

  @doc "Like `stream/2`, but returns the stream or raises."
  @spec stream!(BillionSend.Client.t(), keyword()) :: Enumerable.t()
  def stream!(client, opts \\ []) do
    BillionSend.Client.unwrap!(stream(client, opts))
  end

  @doc """
  Stream one inbox's events.

  BillionSend extension: the event stream of one inbox, as GET /inboxes/events, ending when the inbox is deleted or expires; it carries inbox.deleted and inbox.expired whatever types names. An inbox-scoped key may stream its own inbox, without the events about held mail.

  `GET /inboxes/{inbox_id}/events`

  Options:

    * `:types` - query `types`
    * `:last_event_id` - query `last_event_id`
    * `:last_event_id` - resume after this position
    * `:max_reconnects` - default 5
    * `:extra_headers`, `:timeout`

  Returns `{:ok, stream}`, a lazy Enumerable of `BillionSend.InboxStreamEvent` and `BillionSend.StreamGapEvent` structs (see `BillionSend.EventStream`), or `{:error, error}` when the API refuses the stream.
  """
  @spec stream_inbox(BillionSend.Client.t(), String.t(), keyword()) ::
          {:ok, Enumerable.t()} | {:error, BillionSend.Errors.t()}
  def stream_inbox(client, inbox_id, opts \\ []) do
    BillionSend.Client.check_opts!(
      opts,
      [:types, :last_event_id, :max_reconnects, :extra_headers, :timeout],
      []
    )

    BillionSend.EventStream.open(
      client,
      "/inboxes/#{BillionSend.Client.encode_path(inbox_id)}/events",
      [{"types", Keyword.get(opts, :types)}],
      opts
